def median(values: list[int]) -> float:
    ordered = sorted(values)
    n = len(ordered)
    if n % 2 == 1:
        return float(ordered[n // 2])
    else:
        return float((ordered[n // 2 - 1] + ordered[n // 2]) / 2)

